package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.CollectorNodeFacts;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import org.junit.jupiter.api.Test;
class CollectorNodeWatermarkTest {
 static final Instant START=OperationalRuleEngineTest.START;static final OperationalRuleEngine ENGINE=new OperationalRuleEngine();static final Key HEART=new Key("OPS-02","collector","fictional-node"),DISK=new Key("OPS-05","collector","fictional-node");
 static CollectorNode value(int minute,long node,long history,Instant observed,long queue,int claims){Instant read=START.plusSeconds(60L*minute);var h=history==0?null:new CollectorNodeFacts.Heartbeat(node,history,observed,observed,0,0,0,queue,2L<<30,null);return new CollectorNode(new CollectorNodeFacts.Evidence("fictional-node",node,true,START.minusSeconds(1000),h,claims,read));}
 static State tick(State state,int minute,CollectorNode reading){return ENGINE.sample(state,OperationalRuleEngineTest.config(state.key().ruleId().equals("OPS-02")?2:5),1,START.plusSeconds(60L*minute),true,reading).state();}
 @Test void originalMissingHeartbeatGapAndThreeDifferentRealReconciledHeartbeatsResolve(){State state=tick(State.empty(HEART),0,value(0,1,0,null,0,0));assertEquals(Level.CRITICAL,state.level());assertEquals(0,state.counters().get("heartbeats"));for(int m=1;m<=2;m++){state=tick(state,m,value(m,1,m,START.plusSeconds(m*60L),0,0));assertEquals(Status.ACTIVE,state.status());assertEquals(m,state.counters().get("heartbeats"));}state=tick(state,3,value(3,1,3,START.plusSeconds(180),0,0));assertEquals(Status.RESOLVED,state.status());}
 @Test void reReadingOneOriginalHeartbeatNeverCountsThreeAndNativeMarksSurviveUnknownRestart(){State state=tick(State.empty(HEART),0,value(0,1,0,null,0,0));state=tick(state,1,value(1,1,1,START.plusSeconds(60),0,0));state=OperationalStateCodec.decode(OperationalStateCodec.encode(state));state=tick(state,2,value(2,1,1,START.plusSeconds(60),0,0));assertEquals(0,state.counters().get("heartbeats"));state=tick(state,3,value(3,1,1,START.plusSeconds(60),0,0));assertEquals(Status.ACTIVE,state.status());state=ENGINE.sample(state,OperationalRuleEngineTest.config(2),1,START.plusSeconds(240),false,null).state();assertEquals(1,state.counters().get("node_history"));assertEquals(1,state.counters().get("node_required"));assertEquals(state,OperationalStateCodec.decode(OperationalStateCodec.encode(state)));for(int m=5;m<=7;m++)state=tick(state,m,value(m,1,m,START.plusSeconds(m*60L),0,0));assertEquals(Status.RESOLVED,state.status());}
 @Test void actualNonEmptyServerClaimsPreventHeartbeatRecoveryUntilNativeReconciliation(){State state=tick(State.empty(HEART),0,value(0,1,0,null,0,0));for(int m=1;m<=3;m++)state=tick(state,m,value(m,1,m,START.plusSeconds(60L*m),0,1));assertEquals(Status.ACTIVE,state.status());state=tick(state,4,value(4,1,4,START.plusSeconds(240),0,0));assertEquals(Status.RESOLVED,state.status());}
 @Test void nativeQueueBytesAndFreshnessKeepOriginalImmediateGuardAndTenContinuousMinuteRecovery(){State state=tick(State.empty(DISK),0,value(0,1,1,START,384L<<20,0));assertTrue(state.guards().contains(Guard.NEW_FETCH));for(int m=1;m<=10;m++){state=tick(state,m,value(m,1,m+1,START.plusSeconds(60L*m),0,0));assertTrue(state.guards().contains(Guard.NEW_FETCH));}state=tick(state,11,value(11,1,12,START.plusSeconds(660),0,0));assertEquals(Status.RESOLVED,state.status());assertTrue(state.guards().isEmpty());}
 @Test void oldNodeRevisionAndStaleHeartbeatCannotHealNativeDiskGuard(){State state=tick(State.empty(DISK),0,value(0,1,1,START,384L<<20,0));var old=new CollectorNodeFacts.Heartbeat(1,1,START,START,0,0,0,384L<<20,2L<<30,null);var replaced=new CollectorNode(new CollectorNodeFacts.Evidence("fictional-node",2,true,START,old,0,START.plusSeconds(60)));state=tick(state,1,replaced);assertEquals(Status.TELEMETRY_UNKNOWN,state.status());assertTrue(state.guards().contains(Guard.NEW_FETCH));state=tick(state,2,value(2,2,2,START.plusSeconds(120),0,0));for(int m=3;m<=11;m++){state=tick(state,m,value(m,2,m,START.plusSeconds(60L*m),0,0));assertTrue(state.guards().contains(Guard.NEW_FETCH));}state=tick(state,12,value(12,2,12,START.plusSeconds(720),0,0));assertEquals(Status.RESOLVED,state.status());var stale=value(15,2,13,START.plusSeconds(720),0,0);assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,15,stale).status());}
 @Test void historyRollbackOrSameReceiptDifferentPayloadAndWrongResourceStayUnknown(){State state=tick(State.empty(DISK),0,value(0,1,2,START,384L<<20,0));assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,value(1,1,1,START,0,0)).status());assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,value(1,1,2,START,0,0)).status());var other=new CollectorNode(new CollectorNodeFacts.Evidence("fictional-other",1,true,START,null,0,START.plusSeconds(60)));assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,other).status());assertEquals(Status.TELEMETRY_UNKNOWN,tick(state,1,value(0,1,2,START,384L<<20,0)).status());}
 @Test void syntheticOldReadingCannotReplaceRequiredNativeFactsAndConfigurationGapKeepsMarks(){State state=tick(State.empty(DISK),0,value(0,1,1,START,384L<<20,0));var downgraded=ENGINE.sample(state,OperationalRuleEngineTest.config(5),2,START.plusSeconds(60),true,new Disk(java.math.BigDecimal.ZERO,java.math.BigDecimal.valueOf(2000))).state();assertEquals(Status.TELEMETRY_UNKNOWN,downgraded.status());assertTrue(downgraded.guards().contains(Guard.NEW_FETCH));assertEquals(1,downgraded.counters().get("node_history"));var missing=tick(state,1,new CollectorNode(null));assertEquals(Status.TELEMETRY_UNKNOWN,missing.status());}
 @Test void allNativeFactsParticipateInImmutableSampleHashWhileDiagnosticEvidenceIsRedacted(){var one=value(0,1,1,START,1,0);var two=value(0,1,1,START,2,0);assertNotEquals(one.toString(),two.toString());assertEquals("CollectorNodeFacts[redacted]",one.facts().toString());assertFalse(one.toString().contains("redacted"));var future=new CollectorNode(new CollectorNodeFacts.Evidence("fictional-node",1,true,START,null,0,START.plusSeconds(61)));assertEquals(Status.TELEMETRY_UNKNOWN,tick(State.empty(HEART),0,future).status());}
}
